// Canonical replacement bytes (CONTRACT v2 section 2.1) against a dev set
// derived from the real Python reference (test-support/canonical-devset.json,
// regenerated by test-support/derive-canonical-devset.py), plus properties.
// This file holds no backslash escapes in string literals on purpose.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { LifecycleClientError, canonicalJson } from "../dist/index.js";
import { canonicalizeReplacement, compareCodePoints, pythonFloatRepr } from "../dist/canonical.js";
import { errorShape, thrown } from "../test-support/helpers.mjs";

const devset = JSON.parse(readFileSync(new URL("../test-support/canonical-devset.json", import.meta.url), "utf8"));
const b64 = (text) => new Uint8Array(Buffer.from(text, "base64"));
const hex = (bytes) => Buffer.from(bytes).toString("hex");
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");
const BS = String.fromCharCode(0x5c);
const REFUSED = { code: "INVALID_REQUEST", field: "replacement", retryable: false, nextAction: "NONE", httpStatus: null };

test("dev set: canonical bytes and descriptor digest equal Python's, from bytes and from text", () => {
  assert.ok(devset.vectors.length >= 15);
  for (const v of devset.vectors) {
    const input = b64(v.input_b64);
    const text = new TextDecoder("utf-8", { fatal: true }).decode(input);
    for (const source of [input, text]) {
      assert.equal(hex(canonicalJson(source)), hex(b64(v.canonical_b64)), `${v.name}: canonical bytes`);
      const replacement = canonicalizeReplacement(source);
      assert.equal(hex(replacement.body), hex(b64(v.canonical_b64)), `${v.name}: body`);
      assert.equal(hex(replacement.descriptor), hex(b64(v.descriptor_canonical_b64)), `${v.name}: descriptor`);
      assert.equal(`sha256:${sha256(replacement.descriptor)}`, v.descriptor_digest, `${v.name}: digest`);
    }
  }
});

test("dev set: every contract refusal is INVALID_REQUEST field replacement, nothing echoed", () => {
  assert.ok(devset.refusals.length >= 30);
  for (const r of devset.refusals) {
    const input = b64(r.input_b64);
    const error = thrown(() => canonicalizeReplacement(input));
    assert.ok(error instanceof LifecycleClientError, r.name);
    assert.deepStrictEqual(errorShape(error), REFUSED, r.name);
    assert.equal(error.message, "q-search lifecycle failed (INVALID_REQUEST)", r.name);
  }
});

test("non-text inputs and raw lone surrogates in a JS string are refused", () => {
  const lone = String.fromCharCode(0xd800);
  for (const bad of [
    undefined,
    null,
    42,
    { descriptor: {} },
    [`{"descriptor":{}}`],
    new Uint16Array(4),
    `{"descriptor":{"a":"${lone}"}}`,
    `{"descriptor":{"${lone}":1}}`,
    `{"descriptor":{"a":"${BS}ud83d${String.fromCharCode(0xde00)}"}}`, // escaped high + raw low
    `{"descriptor":{"a":"${String.fromCharCode(0xd83d)}${BS}ude00"}}`, // raw high + escaped low
    String.fromCharCode(0xfeff) + `{"descriptor":{}}`,
  ]) {
    assert.deepStrictEqual(errorShape(thrown(() => canonicalizeReplacement(bad))), REFUSED, String(bad));
  }
});

test("a Buffer and a Uint8Array from another offset are read as bytes; the caller's array is copied", () => {
  const text = `{"descriptor":{"b":1,"a":2}}`;
  const expected = `{"descriptor":{"a":2,"b":1}}`;
  assert.equal(Buffer.from(canonicalJson(Buffer.from(text))).toString(), expected);
  const padded = Buffer.from("xx" + text);
  assert.equal(Buffer.from(canonicalJson(new Uint8Array(padded.buffer, padded.byteOffset + 2, text.length))).toString(), expected);
});

test("pythonFloatRepr: hand-checked Python repr values and round trip", () => {
  const cases = [
    [1, "1.0"],
    [-0, "-0.0"],
    [0, "0.0"],
    [100, "100.0"],
    [0.1, "0.1"],
    [1e16, "1e+16"],
    [1e15, "1000000000000000.0"],
    [1.5e-5, "1.5e-05"],
    [0.0001, "0.0001"],
    [5e-324, "5e-324"],
    [1.7976931348623157e308, "1.7976931348623157e+308"],
    [123456789.123456789, "123456789.12345679"],
    [-2.5e-7, "-2.5e-07"],
    [1e100, "1e+100"],
  ];
  for (const [value, expected] of cases) assert.equal(pythonFloatRepr(value), expected, String(value));
  let seed = 7;
  const random = () => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed / 2147483648;
  };
  const view = new DataView(new ArrayBuffer(8));
  for (let i = 0; i < 5000; i += 1) {
    view.setUint32(0, Math.floor(random() * 2 ** 32));
    view.setUint32(4, Math.floor(random() * 2 ** 32));
    const x = view.getFloat64(0);
    if (!Number.isFinite(x)) continue;
    const text = pythonFloatRepr(x);
    assert.ok(Object.is(Number(text), x), `${text} round-trips`);
    assert.ok(/[.e]/.test(text), `${text} is float-shaped`);
  }
  for (const bad of [Infinity, -Infinity, NaN]) assert.throws(() => pythonFloatRepr(bad));
});

test("compareCodePoints orders by code point, not UTF-16 code unit", () => {
  const astral = String.fromCodePoint(0x1f600);
  const highBmp = String.fromCodePoint(0xff61);
  assert.ok(astral < highBmp, "default JS order is code-unit order");
  assert.equal(compareCodePoints(highBmp, astral), -1);
  assert.equal(compareCodePoints(astral, highBmp), 1);
  assert.equal(compareCodePoints("a", "ab"), -1);
  assert.equal(compareCodePoints("ab", "a"), 1);
  assert.equal(compareCodePoints("", ""), 0);
});

/** Seeded generator of int-only or string-only JSON values. */
function generator(seed) {
  let state = seed;
  const random = () => {
    state = (state * 1103515245 + 12345) % 2147483648;
    return state / 2147483648;
  };
  const pick = (n) => Math.floor(random() * n);
  const POOL = [0x22, 0x5c, 0x2f, 0x00, 0x01, 0x08, 0x09, 0x0a, 0x0c, 0x0d, 0x1f, 0x20, 0x41, 0x7f, 0xe9, 0x2028, 0x2029, 0xfeff, 0xff61, 0x1f600, 0x10ffff];
  // Keys never contain a backslash: the oracle side of the property (V8 JSON.parse on
  // Node 24.18) mis-decodes some escaped keys once a backslash key was parsed. See
  // the pinned regression test below and HILLCLIMB.md. Values keep the backslash.
  const randomString = (forKey = false) => {
    let out = "";
    for (let i = pick(6); i > 0; i -= 1) {
      const cp = random() < 0.7 ? POOL[pick(POOL.length)] : 0x20 + pick(0x5f);
      out += String.fromCodePoint(forKey && cp === 0x5c ? 0x2f : cp);
    }
    return out;
  };
  const randomInt = () => {
    const r = random();
    if (r < 0.2) return 0;
    if (r < 0.3) return -0;
    if (r < 0.5) return pick(1000) - 500;
    return Math.round((random() * 2 - 1) * Number.MAX_SAFE_INTEGER);
  };
  const value = (depth, leaf) => {
    const r = random();
    if (depth > 4 || r < 0.4) return leaf();
    if (r < 0.7) return Array.from({ length: pick(4) }, () => value(depth + 1, leaf));
    const object = {};
    for (let i = pick(5); i > 0; i -= 1) object[randomString(true)] = value(depth + 1, leaf);
    return object;
  };
  return { random, pick, randomString, randomInt, value };
}

/** Serialise with random whitespace and random uXXXX escapes, so the text differs from JSON.stringify. */
function noisyText(value, g) {
  const ws = () => [" ", String.fromCharCode(0x09), String.fromCharCode(0x0a), String.fromCharCode(0x0d), ""][g.pick(5)];
  const str = (s) => {
    let out = '"';
    for (const ch of s) {
      const cp = ch.codePointAt(0);
      if (cp < 0x20 || cp === 0x22 || cp === 0x5c || g.random() < 0.3) {
        for (let i = 0; i < ch.length; i += 1) out += `${BS}u${ch.charCodeAt(i).toString(16).padStart(4, "0")}`;
      } else {
        out += ch;
      }
    }
    return out + '"';
  };
  const emit = (v) => {
    if (typeof v === "string") return str(v);
    if (typeof v === "number") return Object.is(v, -0) ? "-0" : String(v);
    if (Array.isArray(v)) return `[${ws()}${v.map((x) => emit(x)).join(`${ws()},${ws()}`)}${ws()}]`;
    const keys = Object.keys(v).sort(() => g.random() - 0.5);
    return `{${ws()}${keys.map((k) => `${str(k)}${ws()}:${ws()}${emit(v[k])}`).join(`${ws()},${ws()}`)}${ws()}}`;
  };
  return ws() + emit(value) + ws();
}

test("property: canonical(text) == canonical(JSON.stringify(JSON.parse(text))) for int-only and string-only documents", () => {
  const decoder = new TextDecoder();
  for (const [label, seed, leafOf] of [
    ["int-only", 11, (g) => g.randomInt],
    ["string-only", 23, (g) => () => g.randomString()],
  ]) {
    const g = generator(seed);
    for (let i = 0; i < 1500; i += 1) {
      const text = noisyText(g.value(0, leafOf(g)), g);
      const direct = canonicalJson(text);
      const viaJs = canonicalJson(JSON.stringify(JSON.parse(text)));
      assert.equal(hex(direct), hex(viaJs), `${label} #${i}`);
      assert.equal(hex(canonicalJson(direct)), hex(direct), `${label} #${i}: idempotent`);
      const plain = (json) => JSON.parse(json, (_, v) => (Object.is(v, -0) ? 0 : v)); // canonical -0 is 0
      assert.deepStrictEqual(plain(decoder.decode(direct)), plain(text), `${label} #${i}: same value`);
    }
  }
});

test("escaped single-character keys decode exactly, whatever was parsed before (V8 JSON.parse regression guard)", () => {
  // On Node 24.18.0, JSON.parse('{"":0,"<BS>u000d":1}') returns the key "<BS>" (U+005C) instead
  // of CR once '{"":0,"<BS>u005c":1}' was parsed in the same isolate (Node 22 is correct).
  // The canonicaliser never uses JSON.parse; pin its output for exactly that sequence.
  const first = `{"descriptor":{"":0,"${BS}u005c":1}}`;
  const second = `{"descriptor":{"":0,"${BS}u000d":1}}`;
  const secondShort = `{"descriptor":{"":0,"${BS}r":1}}`;
  const decode = (bytes) => Buffer.from(bytes).toString("utf8");
  assert.equal(decode(canonicalJson(first)), `{"descriptor":{"":0,"${BS}${BS}":1}}`);
  for (const text of [second, secondShort]) {
    assert.equal(decode(canonicalJson(text)), `{"descriptor":{"":0,"${BS}r":1}}`);
    assert.equal(decode(canonicalJson(first)), `{"descriptor":{"":0,"${BS}${BS}":1}}`);
  }
});
